import{_ as p,r as s,o,c as l,e as n,a as c,s as u}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Updating the Page - October CMS User Guide","titleTemplate":false,"description":"Replace parts of the page after an AJAX request using push and pull partial updates","frontmatter":{"subtitle":"Replace parts of the page after an AJAX request using push and pull partial updates"},"headers":[{"level":2,"title":"Push: Update from the Handler","slug":"push-update-from-the-handler","link":"#push-update-from-the-handler","children":[{"level":3,"title":"Wrap the Form","slug":"wrap-the-form","link":"#wrap-the-form","children":[]},{"level":3,"title":"Update the Handler","slug":"update-the-handler","link":"#update-the-handler","children":[]},{"level":3,"title":"How Push Updates Work","slug":"how-push-updates-work","link":"#how-push-updates-work","children":[]},{"level":3,"title":"Try It Out","slug":"try-it-out","link":"#try-it-out","children":[]}]},{"level":2,"title":"Pull: Update from a Partial","slug":"pull-update-from-a-partial","link":"#pull-update-from-a-partial","children":[{"level":3,"title":"Create the Partial","slug":"create-the-partial","link":"#create-the-partial","children":[]},{"level":3,"title":"Update the Form","slug":"update-the-form","link":"#update-the-form","children":[]},{"level":3,"title":"Simplify the Handler","slug":"simplify-the-handler","link":"#simplify-the-handler","children":[]},{"level":3,"title":"How Pull Updates Work","slug":"how-pull-updates-work","link":"#how-pull-updates-work","children":[]},{"level":3,"title":"Try It Out","slug":"try-it-out-1","link":"#try-it-out-1","children":[]}]},{"level":2,"title":"Push vs Pull","slug":"push-vs-pull","link":"#push-vs-pull","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/quickstart/interactive-features/flash-messages-and-loaders.md","filePath":"user-guide/quickstart/interactive-features/flash-messages-and-loaders.md"}'),r={name:"user-guide/quickstart/interactive-features/flash-messages-and-loaders.md"};function i(k,a,d,h,g,m){const t=s("pre-heading"),e=s("post-heading");return o(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"Updating the Page",-1)),n(e),a[1]||(a[1]=u(`<p>Flash messages are great for quick feedback, but they fade away. Sometimes you want a permanent change on the page: replace the form with a thank-you message, update a counter, or swap out an entire section. The AJAX framework can do this by updating the DOM after a request completes.</p><p>There are two ways to update the page:</p><ul><li><strong>Push</strong>: the handler decides what HTML to send back and where to put it.</li><li><strong>Pull</strong>: the markup tells the framework which partial to render and where to insert it.</li></ul><p>Let&#39;s try both approaches on our contact form.</p><h2 id="push-update-from-the-handler"><a href="#push-update-from-the-handler" class="header-anchor">#</a> Push: Update from the Handler</h2><p>Right now, after sending a message, the visitor sees a flash notification but the form stays on the page. Let&#39;s replace the form with a confirmation message, pushed from the handler.</p><h3 id="wrap-the-form"><a href="#wrap-the-form" class="header-anchor">#</a> Wrap the Form</h3><ol><li>Open <strong>Editor → Pages → Team Profile</strong>.</li><li>In the <strong>Markup</strong> tab, wrap the entire form (including the heading) in a <code>&lt;div&gt;</code> with an ID:</li></ol><div class="language-twig extra-class"><pre class="language-twig"><code>    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>contact-form<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-xl font-semibold mb-4<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Send <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> section<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span> a Message<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>

        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSendMessage<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-flash</span> <span class="token attr-name">data-request-validate</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mb-4<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>block text-sm font-medium mb-1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Your Email<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span>
                    <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>email<span class="token punctuation">&quot;</span></span>
                    <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>email<span class="token punctuation">&quot;</span></span>
                    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>w-full border rounded-lg px-3 py-2<span class="token punctuation">&quot;</span></span>
                <span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mb-4<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>block text-sm font-medium mb-1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Message<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>textarea</span>
                    <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>message<span class="token punctuation">&quot;</span></span>
                    <span class="token attr-name">rows</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>4<span class="token punctuation">&quot;</span></span>
                    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>w-full border rounded-lg px-3 py-2<span class="token punctuation">&quot;</span></span>
                <span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>textarea</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>bg-blue-600 text-white px-5 py-2.5 rounded-lg hover:bg-blue-700<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-attach-loading</span>
            <span class="token punctuation">&gt;</span></span>
                Send Message
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><ol start="3"><li>Click <strong>Save</strong>.</li></ol><h3 id="update-the-handler"><a href="#update-the-handler" class="header-anchor">#</a> Update the Handler</h3><ol><li>Switch to the <strong>Code</strong> tab.</li><li>Update the <code>onSendMessage</code> handler to return HTML that replaces the form:</li></ol><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSendMessage</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$data</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">validate</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|email&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$member</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">section</span><span class="token operator">-&gt;</span><span class="token function">getRecord</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;message&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$msg</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$member</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$msg</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token variable">$member</span><span class="token operator">-&gt;</span><span class="token property">email</span><span class="token punctuation">,</span> <span class="token variable">$member</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$msg</span><span class="token operator">-&gt;</span><span class="token function">replyTo</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$msg</span><span class="token operator">-&gt;</span><span class="token function">subject</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Message from your profile page&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;#contact-form&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&lt;p class=&quot;text-green-600 font-medium&quot;&gt;Thank you! Your message has been sent to &#39;</span> <span class="token operator">.</span> <span class="token function">e</span><span class="token punctuation">(</span><span class="token variable">$member</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">)</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;.&lt;/p&gt;&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><ol start="3"><li>Click <strong>Save</strong>.</li></ol><h3 id="how-push-updates-work"><a href="#how-push-updates-work" class="header-anchor">#</a> How Push Updates Work</h3><p>When a handler returns an array with a key that starts with <code>#</code> or <code>.</code>, the framework treats it as a DOM update. The key is a CSS selector, and the value is the HTML to insert.</p><p>In our case, <code>&#39;#contact-form&#39;</code> targets the <code>&lt;div id=&quot;contact-form&quot;&gt;</code> wrapper, and the value replaces its entire contents with the confirmation message. The form disappears and the thank-you text takes its place.</p><h3 id="try-it-out"><a href="#try-it-out" class="header-anchor">#</a> Try It Out</h3><ol><li>Preview the site and go to a team member&#39;s profile.</li><li>Fill in the contact form and click <strong>Send Message</strong>.</li><li>The form should be replaced with &quot;Thank you! Your message has been sent to Ada Lovelace.&quot;</li></ol><p>This is a push update. The handler controlled what happened. The browser did not need to know anything about the update in advance.</p><h2 id="pull-update-from-a-partial"><a href="#pull-update-from-a-partial" class="header-anchor">#</a> Pull: Update from a Partial</h2><p>Returning raw HTML from a handler works, but it mixes presentation with logic. A cleaner approach is to use a <strong>partial</strong> for the success message and let the markup request it. This is a pull update.</p><h3 id="create-the-partial"><a href="#create-the-partial" class="header-anchor">#</a> Create the Partial</h3><ol><li>Navigate to <strong>Editor → Partials</strong> and click <strong>+ Add</strong>.</li><li>Name it <code>contact-success</code>.</li><li>Enter:</li></ol><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-green-600 font-medium<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Thank you! Your message has been sent to <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>.
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><ol start="4"><li>Click <strong>Save</strong>.</li></ol><h3 id="update-the-form"><a href="#update-the-form" class="header-anchor">#</a> Update the Form</h3><ol><li>Open <strong>Editor → Pages → Team Profile</strong>.</li><li>In the <strong>Markup</strong> tab, add <code>data-request-update</code> to the form to tell the framework to pull the partial after a successful request:</li></ol><div class="language-twig extra-class"><pre class="language-twig"><code>        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span>
            <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSendMessage<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-request-validate</span>
            <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ &#39;contact-success&#39;: &#39;#contact-form&#39; }<span class="token punctuation">&quot;</span></span>
        <span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Note that we also removed <code>data-request-flash</code> since we no longer need the flash message. The partial update replaces it.</p><ol start="3"><li>Click <strong>Save</strong>.</li></ol><h3 id="simplify-the-handler"><a href="#simplify-the-handler" class="header-anchor">#</a> Simplify the Handler</h3><ol><li>Switch to the <strong>Code</strong> tab.</li><li>Update the handler to set a variable for the partial instead of returning HTML:</li></ol><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSendMessage</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$data</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">validate</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|email&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$member</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">section</span><span class="token operator">-&gt;</span><span class="token function">getRecord</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;message&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$msg</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$member</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$msg</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token variable">$member</span><span class="token operator">-&gt;</span><span class="token property">email</span><span class="token punctuation">,</span> <span class="token variable">$member</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$msg</span><span class="token operator">-&gt;</span><span class="token function">replyTo</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$msg</span><span class="token operator">-&gt;</span><span class="token function">subject</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Message from your profile page&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$member</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><ol start="3"><li>Click <strong>Save</strong>.</li></ol><h3 id="how-pull-updates-work"><a href="#how-pull-updates-work" class="header-anchor">#</a> How Pull Updates Work</h3><p>The <code>data-request-update</code> attribute uses this format:</p><div class="language- extra-class"><pre class="language-text"><code>{ &#39;partial-name&#39;: &#39;#target-selector&#39; }
</code></pre></div><p>After the AJAX request succeeds, the framework asks the server to render the <code>contact-success</code> partial and replaces the contents of <code>#contact-form</code> with the result. The handler only needs to set the variables the partial uses, in this case <code>name</code>.</p><p>This is cleaner because the HTML lives in a partial (where it belongs) and the handler focuses on logic.</p><h3 id="try-it-out-1"><a href="#try-it-out-1" class="header-anchor">#</a> Try It Out</h3><ol><li>Preview the site and submit the contact form again.</li><li>The behavior is the same (the form is replaced with the thank-you message) but now the message comes from a partial.</li></ol><h2 id="push-vs-pull"><a href="#push-vs-pull" class="header-anchor">#</a> Push vs Pull</h2><p>Both approaches achieve the same result. Here is when to use each:</p><div class="table"><table tabindex="0"><thead><tr><th>Approach</th><th>Best For</th></tr></thead><tbody><tr><td><strong>Push</strong> (handler returns HTML)</td><td>Quick updates, simple messages, one-off responses</td></tr><tr><td><strong>Pull</strong> (markup requests a partial)</td><td>Reusable templates, complex HTML, separation of concerns</td></tr></tbody></table></div><p>In practice, pull updates are more common because they keep your HTML in templates where it belongs. Push updates are handy for simple cases where creating a partial feels like overkill.</p><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>You have built a complete interactive feature: a form with validation, email sending, and DOM updates. The Interactive Features section is complete.</p><p>Continue to <a href="./../deployment/preparing-for-production.html">Preparing for Production</a> to get your site ready for the real world.</p><p>For the full reference on partial updates, see <a href="./../../../4.x/cms/ajax/update-partials.html">Updating Partials</a> in the developer documentation.</p>`,50))])}const q=p(r,[["render",i]]);export{v as __pageData,q as default};
